  ($q$Multisyllable & Morphology · Prefixes de, dis$q$, 1, $q$read and spell words with dis-, like dislike, disagree and disappear$q$, ARRAY[$q$RF.3.3A$q$]::text[], ARRAY[$q$ELD-LA.2-3.Narrate.Interpretive$q$, $q$ELD-LA.2-3.Narrate.Expressive$q$]::text[]),
  ($q$Multisyllable & Morphology · Prefixes de, dis$q$, 2, $q$read and spell words with de-, like defend, decrease and depart$q$, ARRAY[$q$RF.3.3A$q$]::text[], ARRAY[$q$ELD-LA.2-3.Narrate.Interpretive$q$, $q$ELD-LA.2-3.Narrate.Expressive$q$]::text[]),
  ($q$Multisyllable & Morphology · Prefixes de, dis$q$, 3, $q$explain that dis- means not or opposite and de- means off or down$q$, ARRAY[$q$L.3.4B$q$]::text[], ARRAY[$q$ELD-LA.2-3.Explain.Expressive$q$]::text[]),
  ($q$Multisyllable & Morphology · Prefixes de, dis$q$, 4, $q$use dis- and de- to work out new words, like dishonest and defrost$q$, ARRAY[$q$L.3.4B$q$]::text[], ARRAY[$q$ELD-LA.2-3.Inform.Interpretive$q$]::text[]),
  ($q$Multisyllable & Morphology · Suffix: ible$q$, 1, $q$read and spell words with -ible, like visible, possible and flexible$q$, ARRAY[$q$RF.3.3B$q$]::text[], ARRAY[$q$ELD-LA.2-3.Narrate.Interpretive$q$, $q$ELD-LA.2-3.Narrate.Expressive$q$]::text[]),
  ($q$Multisyllable & Morphology · Suffix: ible$q$, 2, $q$explain that -ible, like -able, means can be, as in visible$q$, ARRAY[$q$L.3.4B$q$]::text[], ARRAY[$q$ELD-LA.2-3.Explain.Expressive$q$]::text[]),
  ($q$Multisyllable & Morphology · Suffix: ible$q$, 3, $q$use -ible words in sentences, like The stars are visible tonight$q$, ARRAY[$q$L.3.4B$q$]::text[], ARRAY[$q$ELD-LA.2-3.Narrate.Expressive$q$]::text[]),
  ($q$Multisyllable & Morphology · Prefix sub-, trans-$q$, 1, $q$read and spell words with sub-, like subway, submarine and subtract$q$, ARRAY[$q$RF.3.3A$q$]::text[], ARRAY[$q$ELD-LA.2-3.Narrate.Interpretive$q$, $q$ELD-LA.2-3.Narrate.Expressive$q$]::text[]),
  ($q$Multisyllable & Morphology · Prefix sub-, trans-$q$, 2, $q$read and spell words with trans-, like transport and transform$q$, ARRAY[$q$RF.3.3A$q$]::text[], ARRAY[$q$ELD-LA.2-3.Narrate.Interpretive$q$, $q$ELD-LA.2-3.Narrate.Expressive$q$]::text[]),
  ($q$Multisyllable & Morphology · Prefix sub-, trans-$q$, 3, $q$explain that sub- means under and trans- means across$q$, ARRAY[$q$L.3.4B$q$]::text[], ARRAY[$q$ELD-LA.2-3.Explain.Expressive$q$]::text[]),
  ($q$Multisyllable & Morphology · Prefix sub-, trans-$q$, 4, $q$use sub- and trans- to work out words like subzero and transplant$q$, ARRAY[$q$L.3.4B$q$]::text[], ARRAY[$q$ELD-LA.2-3.Inform.Interpretive$q$]::text[]),
  ($q$Multisyllable & Morphology · Suffix -al/-ial (final stable cial, tial)$q$, 1, $q$read and spell words ending in -al, like dismissal, arrival and personal$q$, ARRAY[$q$RF.3.3B$q$]::text[], ARRAY[$q$ELD-LA.2-3.Narrate.Interpretive$q$, $q$ELD-LA.2-3.Narrate.Expressive$q$]::text[]),
  ($q$Multisyllable & Morphology · Suffix -al/-ial (final stable cial, tial)$q$, 2, $q$read words ending in cial and tial, which say shul, like facial and partial$q$, ARRAY[$q$RF.3.3B$q$]::text[], ARRAY[$q$ELD-LA.2-3.Narrate.Interpretive$q$]::text[]),
  ($q$Multisyllable & Morphology · Suffix -al/-ial (final stable cial, tial)$q$, 3, $q$explain that -al can make describing words, like nature to natural$q$, ARRAY[$q$L.3.4B$q$]::text[], ARRAY[$q$ELD-LA.2-3.Explain.Expressive$q$]::text[]),
  ($q$Multisyllable & Morphology · Suffix -al/-ial (final stable cial, tial)$q$, 4, $q$use -al words in sentences, like Her arrival was a special surprise$q$, ARRAY[$q$L.3.4B$q$]::text[], ARRAY[$q$ELD-LA.2-3.Narrate.Expressive$q$]::text[])
) AS v(title, ord, text, ccss, wida)
JOIN curriculum_units u ON u.title = v.title
JOIN curriculum_books bk ON bk.id = u.book_id AND lower(bk.level_number) = lower($q$$q$)
JOIN curriculum_series s ON s.id = bk.series_id AND lower(s.name) = lower($q$Science of Reading$q$)
WHERE NOT EXISTS (SELECT 1 FROM curriculum_unit_objectives o WHERE o.unit_id = u.id);

-- Units still without a bank:
SELECT s.name AS series, bk.level_number AS level, u.title FROM curriculum_units u
JOIN curriculum_books bk ON bk.id = u.book_id JOIN curriculum_series s ON s.id = bk.series_id
WHERE lower(s.name) IN (lower($q$Hand in Hand$q$), lower($q$Into Reading$q$), lower($q$Science of Reading$q$)) AND NOT EXISTS (SELECT 1 FROM curriculum_unit_objectives o WHERE o.unit_id = u.id)
ORDER BY s.name, bk.level_number, u.sort_order;
